//
//  BankLogoPaths.swift
//  nano ewallet
//
//  Logo ngân hàng port từ Android vector drawable (res/drawable/ic_bank_*.xml) —
//  dùng làm watermark tint 1 màu trên BankCard, nên chỉ giữ pathData, bỏ toàn bộ
//  thông tin màu gốc. Tra theo mã BIN, mirror `localBankLogoRes()` trong BankCard.kt.
//
//  BacABank (BIN 970409) không port: vector gốc 63 path/37KB, quá lớn cho watermark
//  — rơi về logo remote qua `logoUrl`.
//

import CoreGraphics

/// Hình logo 1 ngân hàng: viewBox gốc + danh sách pathData (vẽ chồng, cùng 1 màu tint).
struct BankLogoShape {
    let viewBox: CGSize
    let paths: [String]
    /// Vector gốc khai `android:fillType="evenOdd"` — phải fill theo even-odd, không thì
    /// phần lẽ ra rỗng (path sau phủ lên path trước) sẽ bị lấp đầy, logo sai hình.
    var usesEvenOdd: Bool = false
}

enum BankLogoPaths {
    /// Tra logo local theo mã BIN — `nil` nghĩa là chưa port, dùng `logoUrl` remote.
    static func shape(bin: String?) -> BankLogoShape? {
        guard let bin else { return nil }
        return byBin[bin]
    }

